import{_ as i,o as a,c as t,a3 as e}from"./chunks/framework.WFmvnizL.js";const c=JSON.parse('{"title":"Configuration recipes and verification","description":"Practical Nezha Monitoring V2 recipes for HTTPS proxies, built-in TLS, lightweight Agents, restricted operations, online history, and TSDB, with verification and rollback.","frontmatter":{"description":"Practical Nezha Monitoring V2 recipes for HTTPS proxies, built-in TLS, lightweight Agents, restricted operations, online history, and TSDB, with verification and rollback.","outline":"deep"},"headers":[],"relativePath":"en_US/configuration/examples.md","filePath":"en_US/configuration/examples.md","lastUpdated":1792850916000}'),n={name:"en_US/configuration/examples.md"};function l(h,s,r,p,o,d){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="configuration-recipes-and-verification" tabindex="-1">Configuration recipes and verification <a class="header-anchor" href="#configuration-recipes-and-verification" aria-label="Permalink to &quot;Configuration recipes and verification&quot;">​</a></h1><p>These are <strong>fragments to merge into existing files</strong>, not complete replacements for production configuration. Identify the <a href="/en_US/configuration/environment.html">active configuration sources</a>, preserve secrets and UUIDs, and replace example domains.</p><h2 id="https-reverse-proxy" tabindex="-1">HTTPS reverse proxy <a class="header-anchor" href="#https-reverse-proxy" aria-label="Permalink to &quot;HTTPS reverse proxy&quot;">​</a></h2><p>Assume the proxy and Dashboard run on the same host, exposed as <code>https://monitor.example.com</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">listen_host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">listen_port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8008</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">install_host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;monitor.example.com:443&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dashboard_host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;monitor.example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">reserved_hosts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;monitor.example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">web_real_ip_header</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;X-Real-IP&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">agent_real_ip_header</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;X-Real-IP&quot;</span></span></code></pre></div><p>Matching Agent fragment:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;monitor.example.com:443&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">insecure_tls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">report_delay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span></code></pre></div><p>The proxy must forward HTTP/WebSocket and gRPC over HTTP/2, set trustworthy real-IP headers, and prevent bypass access to the backend. See the complete <a href="/en_US/guide/q3.html">reverse-proxy guide</a>. A working homepage alone is not sufficient verification.</p><p>Inside Docker, <code>127.0.0.1</code> is the container&#39;s own loopback. For published ports, bind Dashboard to a reachable container address and restrict publication on the host, for example <code>127.0.0.1:8008:8008</code>. A separate proxy container should use their shared container network. Do not copy the bare-metal bind address unchanged.</p><p><strong>Verify:</strong> user and <code>/dashboard/</code> pages load; WebSocket returns <code>101</code> and streams updates; Agents remain online; reported client IPs are correct. <strong>Rollback:</strong> restore the original files and proxy configuration and restart the relevant services. Do not hide certificate errors by disabling verification.</p><h2 id="dashboard-built-in-https" tabindex="-1">Dashboard built-in HTTPS <a class="header-anchor" href="#dashboard-built-in-https" aria-label="Permalink to &quot;Dashboard built-in HTTPS&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">listen_host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">listen_port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8008</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">https</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  listen_port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8443</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tls_cert_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/etc/nezha/tls/fullchain.pem&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tls_key_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/etc/nezha/tls/privkey.pem&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">install_host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;monitor.example.com:8443&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dashboard_host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;monitor.example.com:8443&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">reserved_hosts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;monitor.example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>Certificate and key paths must be readable inside the process/container, and the certificate must match the hostname. Built-in HTTPS <strong>adds</strong> a listener; it does not disable the HTTP <code>listen_port</code>. Restrict plaintext access through firewall or container publication rules. <code>https.insecure_tls</code> is not a switch that makes clients trust self-signed certificates.</p><p><strong>Verify:</strong> access the selected HTTPS port, validate the certificate chain, and connect a test Agent with the matching address and <code>insecure_tls: false</code>. Logs should reflect the actual listeners.</p><h2 id="lightweight-collection-and-explicit-interfaces" tabindex="-1">Lightweight collection and explicit interfaces <a class="header-anchor" href="#lightweight-collection-and-explicit-interfaces" aria-label="Permalink to &quot;Lightweight collection and explicit interfaces&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">report_delay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ip_report_period</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1800</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">skip_connection_count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">skip_procs_count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">gpu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">temperature</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">nic_allowlist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  eth0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">hard_drive_partition_allowlist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/&quot;</span></span></code></pre></div><p>Replace <code>eth0</code> and mount paths with actual names. A nonempty NIC map is an allowlist, not merely a list of interfaces to exclude when false. Unlisted interfaces are excluded too. An empty map uses built-in filtering rather than unconditionally counting every virtual interface. See <a href="/en_US/guide/q7.html">custom collection</a> for partition selection.</p><p><strong>Verify:</strong> compare host load, speed, and capacity against system tools. Check for omitted primary interfaces and double-counted container bridges. Less frequent reporting reduces chart detail and can affect observation of short anomalies.</p><h2 id="metrics-only-without-remote-operations" tabindex="-1">Metrics-only, without remote operations <a class="header-anchor" href="#metrics-only-without-remote-operations" aria-label="Permalink to &quot;Metrics-only, without remote operations&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable_command_execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable_nat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable_send_query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable_auto_update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable_force_update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>This profile suits nodes with manually maintained binaries and host-metrics-only requirements. It restricts commands, terminal/file operations, remote configuration, NAT, and TCP/ICMP/HTTP probes. It also blocks legitimate service monitoring and MCP remediation, so it is not a universal recommended default.</p><p><strong>Verify:</strong> host metrics continue updating while restricted tasks are rejected. <strong>Rollback:</strong> edit locally and restart. Once commands are disabled, do not depend on Dashboard to re-enable them remotely.</p><h2 id="online-history-and-time-series-storage" tabindex="-1">Online history and time-series storage <a class="header-anchor" href="#online-history-and-time-series-storage" aria-label="Permalink to &quot;Online history and time-series storage&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">online_stats_days</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tsdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  data_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/tsdb&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  retention_days</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  min_free_disk_space_gb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_memory_mb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">256</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  write_buffer_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">512</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  write_buffer_flush_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">memory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  go_mem_limit_mb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">768</span></span></code></pre></div><p>Adjust memory budgets for hardware and fleet size; the example is not a capacity guarantee. <code>go_mem_limit_mb</code> is a Go runtime soft limit, not a process/container hard cap. TSDB cache memory is not the entire process footprint.</p><p>First-time TSDB enablement drops the old <code>service_histories</code> table without migrating its history. Back up first. Online sessions remain database-backed and do not depend on TSDB. Relative <code>data_path</code> uses the working directory; persist that location inside containers.</p><p><strong>Verify:</strong> logs show <code>TSDB initialized successfully</code>, settings return <code>tsdb_enabled: true</code>, newly collected historical metrics can be queried, and disk space is sufficient. Public online-history limits still apply: retaining 30 days does not let guests query all 30 days.</p><p><strong>Rollback:</strong> stop the process and restore configuration and backups. Clearing <code>data_path</code> alone does not restore deleted legacy history. See the <a href="/en_US/guide/q15.html">TSDB guide</a>.</p><h2 id="symptom-lookup" tabindex="-1">Symptom lookup <a class="header-anchor" href="#symptom-lookup" aria-label="Permalink to &quot;Symptom lookup&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check first</th></tr></thead><tbody><tr><td>Homepage works, Agent offline</td><td>gRPC/HTTP2 forwarding, Agent address/TLS, user connection secret</td></tr><tr><td>Page loads without live updates</td><td>WebSocket upgrade and proxy headers, not the reporting interval first</td></tr><tr><td>Settings disappear after container recreation</td><td>Persistent mounts for configuration, database, and TSDB</td></tr><tr><td>Remote configuration accepted but unchanged</td><td>Application delay, persistence errors, startup-only consumers, environment overrides</td></tr><tr><td>Virtual interface missing</td><td>Default filtering and <code>nic_allowlist</code>, not Dashboard charts first</td></tr><tr><td>Old history absent after TSDB enablement</td><td>No automatic legacy-table migration; verify new data, actual path, and disk state</td></tr></tbody></table>`,30)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
